REGEX = [
 (r"^(\d+)×/sem$", "$1×/wk", "$1×/sem"),
 (r"^(\d+) dias$", "$1 days", "$1 días"),
 (r"^(.+): alvos e itens relacionados$", "$1: targets and related items", "$1: dianas y elementos relacionados"),
 (r"^(.+): o que age aqui$", "$1: what acts here", "$1: qué actúa aquí"),
 (r"^Itens que atuam neste alvo \((\d+)\)$", "Items that act on this target ($1)", "Elementos que actúan en esta diana ($1)"),
 (r"^📄 Abrir a ficha de (.+)$", "📄 Open the profile of $1", "📄 Abrir la ficha de $1"),
 (r"^📄 Abrir a página de (.+)$", "📄 Open the page of $1", "📄 Abrir la página de $1"),
 (r"^Última conferência geral do catálogo: (.+)\. A Anvisa não tem API pública: faça a busca diretamente no site\.$", "Last general check of the catalog: $1. Anvisa has no public API: search directly on its site.", "Última revisión general del catálogo: $1. Anvisa no tiene API pública: busque directamente en su sitio."),
 (r"^(.+) ÷ (.+) UI/mg = (.+) mg$", "$1 ÷ $2 IU/mg = $3 mg", "$1 ÷ $2 UI/mg = $3 mg"),
]
